tafsir_text:
وقوله :  {  قُلْ لِّلَّذِينَ كَفَرُواْ سَتُغْلَبُونَ .  .  .  }

تقرأ بالتاء والياء .  فمن جعلها بالياء فإنه ذهب إلى مخاطبة اليهود ،  وإلى أن الغلبة على المشركين [ بعد ] يوم أُحُد .  وذلك أن النبيّ صلى الله عليه وسلم لما هزم المشركين يوم بدر وهم ثلاثمائة ونيّف والمشركون ألف إلا شيئا قالت اليهود :  هذا الذي لا تردّ له راية ،  فصدِّقوا .  فقال بعضهم :  لا تعجَلوا بتصديقه حتى تكون وقعةٌ أخرى .  فلما نُكِب المسلمون يوم أُحُد كذَّبوا ورجعوا .  فأنزل الله :  قل لليهود سيُغلب المشركون ويحشرون إلى جهنم .  فليس يجوز في هذا المعنى إلا الياء .

ومن قرأ بالتاء جعل اليهود والمشركين داخلين في الخطاب .  فيجوز في هذا المعنى سيُغلَبون وستُغْلَبون ؛  كما تقول في الكلام :  قل لعبد الله إنه قائم ،  وإنك قائم .  وفي حرف عبد الله {  قل للذين كفروا إن تنتهوا يغفر لكم ما قد سلف } وفي قراءتنا  " [ إن ينتهوا ] يُغْفَر لهم ما قد سلف "  وفي الأنعام {  هذا لِلَّه بِزَعْمِهمْ وهَذَا لِشُركَائهم } وفي قراءتنا  " لشركائنا "  .

وقوله :  {  الَّذِينَ يَقُولُونَ .  .  .  }

إن شئت جعلته خفضا نعتا للذين اتقوا ،  وإن شئت استأنفتها فرفعتها إذ كانت آية وما هي نعت له آيةٌ قبلها .  ومثله قول الله تبارك وتعالى

{  إنّ اللهََ اشْتَرَى مِنَ الْمُؤْمِنينَ أَنْفُسَهُمْ وَأَمْوَالَهُمْ } فلما انقضت الآية قال {  التّائبُونَ الْعَابِدُونَ } ،  وهي في قراءة عبد الله  " التائبين العابدين "  .

وقوله :  {  تُولِجُ اللَّيْلَ فِي الْنَّهارِ وَتُولِجُ النَّهارَ فِي الْلَّيْلِ .  .  .  }

جاء التفسير أنه نقصان الليل يولَج في النهار ،  وكذلك النهار يولَج في الليل ،  حتى يتناهى طولُ هذا وقِصَر هذا .

وقوله {  وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ } ذُكر عن ابن عباس أنها البيضة :  ميتة يخرج منها الفرخ حيّا ،  والنُطْفة :  ميتة يخرج منها الولد .

وقوله :  {  يَعْلَمْهُ اللَّهُ .  .  .  }

جزم على الجزاء .  {  وَيَعْلَمُ ما فِي السَّماوَاتِ وَما فِي الأَرْضِ } رفع على الاستئناف ؛  كما قال الله في سورة براءة {  قاتِلوهم يعذِّبْهم الله } فجزم الأفاعيل ،  ثم قال {  ويتوبُ الله على من يشاء } رفعا على الاسئتناف .  وكذلك قوله {  فإن يشأ الله يختِمْ على قلبِك } ثم قال {  ويمح الله الباطِل } ويَمْحُ في نِيَّة رفع مستأنفة وإن لم تكن فيها واو ؛  حذفت منها الواو كما حذفت في قوله {  سندعُ الزّبانية } .  وإذا عطفت على جواب الجزاء جاز الرفع والنصب والجزم .  وأما قوله {  وإن تبدوا ما في أنفسِكم أو تخفوه يحاسِبْكم بِهِ الله فيغفِرُ } وتقرأ جزما على العطف ومسكَّنة تشبه الجزم وهي في نية رفع تدغم الراء من يغفر عند اللام ،  والباء من يعذب عند الميم ؛  كما يقال

{  أرَأَيْتَ الذي يُكذِّب بِالدّين } وكما قرأ الحسن {  شهر رمضان } .

وقوله :  {  يَوْمَ تَجِدُ كُلُّ نَفْسٍ ما عَمِلَتْ مِنْ خَيْرٍ مُّحْضَراً .  .  .  }

ما في مذهب الذي .  ولا يكون جزاء لأن ( تجد ) قد وقعت على ما .

وقوله {  وَما عَمِلَتْ مِن سُوءٍ } فإنك تردّه أيضا على ( ما ) فتجعل ( عملت ) صلة لها في مذهب رفع لقوله {  تَوَدُّ لَوْ أَنَّ بَيْنَها } ولو استأنفتها فلم توقع عليها ( تجد ) جاز الجزاء ؛  تجعل ( عملت ) مجزومة .  ويقول في تودّ :  تودَّ بالنصب وتودِّ .  ولو كان التضعيف ظاهر لجاز تَوْدَدْ .  وهي في قراءة عبد الله  " وما عملت من سوء ودَّت "  فهذا دليل على الجزم ،  ولم أسمع أحدا من القراء قرأها جزما .

وقوله :  {  إِنَّ اللَّهَ اصْطَفى آدَمَ وَنُوحا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ على الْعَالَمِينَ .  .  .  }

يقال اصطفى دينهم على جميع الأديان ؛  لأنهم كانوا مسلمين ،  ومثله مما أضمر فيه شيء فأُلقِي قوله {  واسألِ القرية التي كنا فيها } .

ثم قال {  ذرية بعضها مِن بعضٍ } فنصب الذرّية على جهتين ؛  إحداهما أن تجعل الذرّية قطعا من الأسماء قبلها لأنهن معرفة .  وإن شئت نصبت على التكرير ،  اصطفى ذرّية بعضها من بعض ،  ولو استأنفت فرفعت كان صوابا .

وقوله :  {  إِذْ قَالَتِ الْمَلائكَةُ يا مَرْيَمُ إِنَّ اللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ اسْمُهُ .  .  .  }

مما ذكرت لك في قوله {  ذُرّيَّةً طَيِّبَةً } قيل فيها ( اسمه ) بالتذكير للمعنى ،  ولو أنَّث كما قال {  ذُرّيَّةً طَيِّبَةً } كان صوابا .

وقوله :  ( وَجِيها ) قطعا من عيسى ،  ولو خفضت على أن تكون نعتا للكلمة لأنها هي عيسى كان صوابا .

وقوله :  {  وَمُصَدِّقاً }

نصبت ( مصدّقا ) على فِعل ( جئت ) ،  كأنه قال :  وجِئتكم مصدّقا لِما بين يدىّ من التوراة ،  وليس نصبُه بتابع لقوله ( وَجِيها ) لأنه لو كان كذلك لكان ( ومصدّقا لما بين يديه ) .

وقوله :  {  وَلأُحِلَّ لَكُم } الواو فيها بمنزلة قوله {  وكذَلِكَ نُرِى إِبرَاهِيمَ مَلَكُوتَ السَّمَاوَاتِ وَالأَرْضِ وَلِيَكُونَ مِنَ الْمُوقِنِين } .

وقوله :  {  إِذْ قَالَ اللَّهُ يا عِيسَى إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ }

يقال :  إن هذا مقدّم ومؤخَّر .  والمعنى فيه :  إني رافعك إلىَّ ومطهِّرك من الذين كفروا ومتوفِّيك بعد إنزالي إيّاك في الدنيا .  فهذا وجه .

وقد يكون الكلام غير مقدّم ولا مؤخَّر ؛  فيكون معنى متوفّيك :  قابضك ؛  كما تقول :  توفيت مالي من فلان :  قبضته من فلان .  فيكون التوفي على أخذه ورفعه إليه من غير موت .

فقال :  {  هاأَنْتُمْ هَؤُلاء حاجَجْتُمْ }

إلى آخر الآية .  ثم بيَّن ذلك .

فقال :  {  ما كَانَ إِبْرَاهِيمُ يَهُودِيّاً وَلاَ نَصْرَانِيّاً وَلَكِن كَانَ حَنِيفاً مُّسْلِما }

إلى آخر الآية .

فأما قوله :  {  وَلاَ تُؤْمِنُواْ إِلاَّ لِمَن تَبِعَ دِينَكُمْ }

فأنه يقال :  إنها من قول اليهود .  يقول :  ولا تصدقوا إلا لمن تبع دينكم .  واللام بمنزلة قوله :  {  عَسَى أَنْ يَكُونَ رَدِفَ لَكُمْ } المعنى :  ردِفكم .

وقوله :  {  أَن يُؤْتَى أَحَدٌ مِّثْلَ ما أُوتِيتُمْ }

يقول :  لا تصدّقوا أن يؤتَى أحد مثل ما أوتيتم .  أوقعت {  تؤمنوا } على {  أن يؤتى } كأنه قال :  ولا تؤمنوا أن يعطى أحد مثل ما أُعطِيتم ،  فهذا وجه .

ويقال :  قد انقطع كلام اليهود عند قوله {  وَلاَ تُؤْمِنُواْ إِلاَّ لِمَن تَبِعَ دِينَكُمْ } ،  ثم صار الكلام من قوله قل يا محمد إن الهدى هدى الله أن يؤتى أحد مثل ما أوتي أهل الإسلام ،  وجاءت ( أن ) لأنّ في قوله {  قُلْ إِنَّ الْهُدَى } مثلَ قوله :  إن البيان بيان الله ،  فقد بيّن أنه لا يؤتى أحد مثل ما أوتي أهلُ الإسلام .  وصلحت ( أحد ) لأن معنى أن معنى لا كما قال تبارك وتعالى {  يُبَيِّنُ اللهُ لَكُمْ أنْ تَضِلُّوا } معناه :  لا تضلّون .  وقال تبارك وتعالى {  كَذَلِكَ سَلَكْناهُ في قُلُوبِ المُجْرِمينَ .  لاَ يُؤْمِنُونَ بِهِ } أن تصلح في موضع لا .

وقوله {  أوْ يُحاجُّوكُمْ عِنْد رَبِّكُمْ } في معنى حَتَّى وفي معنى إلاّ ؛  كما تقول في الكلام :  تعلَّقْ به أبدا أو يعطيَك حقّك ،  فتصلح حتَّى وإلاَّ في موضع أو .

وقوله :  {  إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلناسِ .  .  .  }

يقول :  إنّ أوّل مسجد وُضع للناس {  لَلَّذِي بِبَكَّةَ } وإنما سمّيت بَكّة لازدحام الناس بها ؛  يقال :  بَكَّ الناسُ بعضُهم بعضا :  إذا ازدحموا .

وقوله :  {  هُدىً } موضع نصب متبعة للمبارك .  ويقال إنْما قيل :  مباركا لأنه مغفِرة للذنوب .

وقوله :  {  فِيهِ آيَاتٌ بَيِّناتٌ .  .  .  }

يقال :  الآيات المقامُ والْحِجر والحَطِيم ،  وقرأ ابن عباس  " فيه آية بيِّنة "  جعل المقام هو الآية لا غير .

وقوله :  {  وَمَن كَفَرَ } يقول :  من قال ليس على حجّ فإنما يجحد بالكفر فرضه لا يتركه .

وقوله :  {  يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ .  .  .  }

لم يذكِّر الفعلَ أحد من القرّاء كما قيل ( لن ينال الله لحومها ولا دماؤها ) وقوله ( لا يحِلّ لك النِساء مِن بعد ) وإنما سهل التذكير في هذين لأن معهما جحدا ،  والمعنى فيه :  لا يحلّ لك أحد من النساء ،  ولن ينال الله شيء من لحومها ،  فذهب بالتذكير إلى المعنى ،  والوجوه ليس ذلك فيها ،  ولو ذكِّر فعل الوجوه كما تقول :  قام القوم لجاز ذلك .

وقوله :  {  فَأَما الَّذِينَ اسْوَدَّتْ وُجُوهُهُمْ أَكْفَرْتُمْ } يقال :  ( أما ) لا بدّ لها من الفاء جوابا فأين هي ؟  فيقال :  إنها كانت مع قولٍ مضمر ،  فلما سقط القول سقطت الفاء معه ،  والمعنى - والله أعلم - فأما الذين اسودّت وجوههم فيقال :  أكفرتم ،  فسقطت الفاء مع ( فيقال ) .  والقول قد يضمر .  ومنه في كتاب الله شيء كثير ؛  من ذلك قوله {  ولو ترى إِذِ المجرِمون ناكِسوا رءوسِهِم عِند ربهم ربنا أبصرنا وسمِعنا } وقوله {  وإِذ يرفع إِبراهِيم القواعِد من البيت وإِسماعيل ربنا تقبل منا } وفي قراءة عبد الله  " ويقولان ربَّنا "  .

وقوله :  {  هاأَنْتُمْ أُوْلاء }

العرب إذا جاءت إلى اسم مكنىّ قد وُصِف بهذا وهاذان وهؤلاء فرّقوا بين ( ها ) وبين ( ذا ) جعلوا المكنَّى بينهما ،  وذلك في جهة التقريب لا في غيرها ،  فيقولون :  أين أنت ؟  فيقول القائل :  هأنذا ،  ولا يكادون يقولون :  هذا أنا ،  وكذلك التثنية والجمع ،  ومنه {  ها أَنْتُمْ أُوْلاء تُحِبُّونَهُمْ } وربما أعادوا ( ها ) فوصلوها بذا وهذان وهؤلاء ؛  فيقولون :  ها أنت هذا ،  وها أنتم هؤلاء ،  وقال الله تبارك وتعالى في النساء :  {  ها أنتم هؤلاء جادلتم عنهم } .

فإذا كان الكلام على غير تقريب أو كان مع اسم ظاهر جعلوا ( ها ) موصولة بذا ،  فيقولون :  هذا هو ،  وهذان هما ،  إذا كان على خبر يكتفي كلُّ واحد بصاحبه بلا فِعل ،  والتقريب لا بدّ فيه من فعل لنقصانه ،  وأحبوا أن يفرقوا بذلك بين معنى التقريب وبين معنى الاسم الصحيح .

وقوله :  {  بَلْ أَحْيَاء عِندَ رَبِّهِمْ يُرْزَقُونَ .  .  .  }

وقوله :  {  فَرِحِينَ .  .  .  }

[ لو كانت رفعا على  " بل أحياء فرحون "  لجاز .  ونصبها على الانقطاع من الهاء في  " ربهم "  .  وإن شئت يرزقون فرحين ] {  وَيَسْتَبْشِرُونَ بِالَّذِينَ لَمْ يَلْحَقُواْ بِهِم مِّنْ خَلْفِهِمْ } من إخوانهم الذين يرجون لهم الشهادة للذي رأوا من ثواب الله فهم يستبشرون بهم .

وقوله :  {  أَلاَّ خَوْفٌ عَلَيْهِمْ } يستبشرون لهم بأنهم لا خوف عليهم  " ولا حزن "  .

وقوله :  {  حَتَّى يَأْتِيَنا بِقُرْبَانٍ تَأْكُلُهُ النارُ .  .  .  }

كان هذا .  والقربان نار لها حفيف وصوت شديد كانت تنزل على بعض الأنبياء .

فلما قالوا ذلك للنبي صلى الله عليه وسلم قال الله تبارك وتعالى  " قل "  يا محمد {  قَدْ جَاءكُمْ رُسُلٌ مِّن قَبْلِي بِالْبَيِّناتِ } وبالقربان الذي قلتم {  فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَادِقِينَ } .

وقوله :  {  لاَ تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِما أَتَوْاْ وَّيُحِبُّونَ أَن يُحْمَدُواْ بِما لَمْ يَفْعَلُواْ .  .  .  }

يقول :  بما فعلوا ؛  كما قال :  {  لقد جئتِ شيئا فرِيا } كقوله :  {  واللذان يَأْتِيانِها مِنكم } وفي قراءة عبد الله  " فمن أتى فاحشة فعله "  .  وقوله :  {  ويُحِبُّون أَن يُحْمَدُوا بِما لم يفعلوا } قالوا :  نحن أهل العلم الأوّل والصلاة الأولى ،  فيقولون ذلك ولا يقرّون بمحمد صلى الله عليه وسلم ،  فذلك قوله :  {  ويُحِبُّون أن يُحْمدوا بِما لم يَفْعَلُوا } .

وقوله :  {  فَلاَ تَحْسَبَنَّهُمْ بِمَفَازَةٍ مِّنَ الْعَذَابِ } .  يقول :  ببعيد من العذاب .  ( قال قال الفراء :  من زعم أن أوفي هذه الآية على غير معنى بل فقد افترى على الله ؛  لأن الله تبارك وتعالى لا يَشُكّ ،  ومنه قول الله تبارك وتعالى :  {  وأرسلناه إلى مائةِ ألفٍ أَو يزِيدون } .  )
